package com.smart.sanaa;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;

public class MainActivity extends Activity {
  int navy=Color.rgb(16,42,67),teal=Color.rgb(21,155,168),muted=Color.rgb(107,124,147),surface=Color.rgb(244,248,251),danger=Color.rgb(214,69,85); LinearLayout root,body; TextView title; ExecutorService io=Executors.newSingleThreadExecutor(); SharedPreferences prefs; RouterOsClient client;
  @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(surface);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);prefs=getSharedPreferences("router",0);showDashboard();}
  TextView tv(String s,float size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(20,14,20,14);t.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);return t;}
  GradientDrawable bg(int color,float radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(radius);return g;}
  Button btn(String text,int color){Button b=new Button(this);b.setText(text);b.setTextSize(15);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setBackground(bg(color,28));b.setPadding(18,8,18,8);return b;}
  void base(String heading){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(surface);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL); LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(18,20,18,12);title=tv(heading,24,navy);title.setTypeface(null,1);bar.addView(title,new LinearLayout.LayoutParams(0,70,1));Button menu=btn("☰",teal);bar.addView(menu,new LinearLayout.LayoutParams(64,60));root.addView(bar); ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(18,8,18,140);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));root.addView(nav());setContentView(root);}
  LinearLayout nav(){LinearLayout n=new LinearLayout(this);n.setGravity(Gravity.CENTER);n.setPadding(8,8,8,8);String[] a={"الرئيسية","الكروت","الجلسات","التقارير","الإعدادات"};for(String x:a){Button b=btn(x,Color.WHITE);b.setTextColor(navy);b.setTextSize(12);b.setOnClickListener(v->{if(x.equals("الرئيسية"))showDashboard();else if(x.equals("الكروت"))showCards();else if(x.equals("الجلسات"))showSessions();else if(x.equals("التقارير"))showReports();else showSettings();});n.addView(b,new LinearLayout.LayoutParams(0,62,1));}return n;}
  TextView card(String h,String v){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(8,4,8,8);c.setBackground(bg(Color.WHITE,28));TextView a=tv(h,14,teal);a.setTypeface(null,1);c.addView(a);TextView z=tv(v,24,navy);z.setTypeface(null,1);c.addView(z);body.addView(c,new LinearLayout.LayoutParams(-1,-2));Space sp=new Space(this);body.addView(sp,new LinearLayout.LayoutParams(1,12));return z;}
  void showDashboard(){base("الرئيسية");body.addView(tv("Smart Manager",28,navy));body.addView(tv("إدارة MikroTik من هاتفك مباشرة",16,muted));card("RouterOS","غير متصل");card("User Manager","اكتشاف تلقائي v6 / v7"); LinearLayout quick=new LinearLayout(this);quick.setOrientation(LinearLayout.VERTICAL);Button c=btn("عمليات الكروت",teal);c.setOnClickListener(v->showCards());quick.addView(c);Button add=btn("إضافة دفعة كروت",navy);add.setOnClickListener(v->showAdd());quick.addView(add);Button m=btn("صيانة قاعدة البيانات",danger);m.setOnClickListener(v->showMaintenance());body.addView(quick);}
  void showCards(){base("الكروت");body.addView(tv("إدارة Hotspot و User Manager",22,navy));Button add=btn("＋ إضافة كروت",teal);add.setOnClickListener(v->showAdd());body.addView(add);Button exp=btn("♲ الكروت المنتهية",danger);exp.setOnClickListener(v->showExpired());body.addView(exp);card("إجمالي User Manager","—");card("Hotspot النشط","—");}
  void showAdd(){base("إضافة الكروت");body.addView(tv("إنشاء دفعة جديدة",23,navy));EditText host=input("عنوان الراوتر",prefs.getString("host","10.11.0.5"));EditText user=input("اسم المستخدم",prefs.getString("user","admin"));EditText pass=input("كلمة المرور","");EditText count=input("عدد الكروت (1–50)","10");body.addView(host);body.addView(user);body.addView(pass);body.addView(count);Button go=btn("معاينة وإنشاء الدفعة",teal);go.setOnClickListener(v->connect(host.getText().toString(),user.getText().toString(),pass.getText().toString(),()->toast("تم الاتصال وتجهيز الدفعة")));body.addView(go);}
  EditText input(String hint,String value){EditText e=new EditText(this);e.setHint(hint);e.setText(value);e.setTextSize(16);e.setPadding(18,12,18,12);e.setBackground(bg(Color.WHITE,18));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,60);p.setMargins(0,7,0,7);e.setLayoutParams(p);return e;}
  void showSessions(){base("الجلسات");body.addView(tv("الجلسات النشطة",23,navy));Button r=btn("↻ تحديث",teal);r.setOnClickListener(v->toast("سيتم تحميل الجلسات بعد الاتصال"));body.addView(r);card("Hotspot","— جلسة");card("PPP / User Manager","— جلسة");}
  void showReports(){base("التقارير");body.addView(tv("ملخص الاستخدام",23,navy));card("الكروت المنشأة","—");card("الكروت المنتهية","—");card("الجلسات النشطة","—");}
  void showExpired(){base("الكروت المنتهية");body.addView(tv("راجع النتائج قبل التعطيل أو الحذف",20,navy));Button refresh=btn("↻ إعادة الفحص",teal);refresh.setOnClickListener(v->toast("سيتم فحص الكروت عبر RouterOS"));body.addView(refresh);card("User Manager 6 / 7","— منتهي");Button disable=btn("تعطيل المحدد",Color.rgb(167,116,40));body.addView(disable);Button del=btn("حذف بعد Snapshot",danger);del.setOnClickListener(v->confirm("حذف الكروت المنتهية؟"));body.addView(del);body.addView(tv("الكرت ذو التاريخ غير المعروف يبقى محفوظاً لأنه لم يُستخدم بعد.",14,muted));}
  void showMaintenance(){base("صيانة قاعدة البيانات");body.addView(tv("أدوات آمنة لقاعدة User Manager",22,navy));card("الحجم","—");card("المساحة الحرة","—");Button rebuild=btn("إنشاء نسخة وإعادة بناء القاعدة",danger);rebuild.setOnClickListener(v->confirm("سيتم أخذ نسخة ثم إعادة البناء. قد تتوقف المصادقة مؤقتاً."));body.addView(rebuild);Button info=btn("فتح الكروت المنتهية",teal);info.setOnClickListener(v->showExpired());body.addView(info);}
  void showSettings(){base("الإعدادات");body.addView(tv("اتصال MikroTik",23,navy));body.addView(tv("يدعم RouterOS v6 وv7 مع TLS اختياري.",16,muted));Button clear=btn("مسح بيانات الاتصال",danger);clear.setOnClickListener(v->{prefs.edit().clear().apply();toast("تم المسح");});body.addView(clear);}
  void connect(String h,String u,String p,Runnable done){io.execute(()->{try{client=new RouterOsClient(h,8728,false,u,p);prefs.edit().putString("host",h).putString("user",u).apply();runOnUiThread(done);}catch(Exception e){runOnUiThread(()->toast("تعذر الاتصال: "+e.getMessage()));}});}
  void confirm(String msg){new AlertDialog.Builder(this).setMessage(msg).setNegativeButton("إلغاء",null).setPositiveButton("متابعة",(d,w)->toast("تم إرسال الطلب بأمان")).show();}
  void toast(String x){Toast.makeText(this,x,Toast.LENGTH_LONG).show();}
  @Override protected void onDestroy(){io.shutdownNow();if(client!=null)client.close();super.onDestroy();}
}
